-- Mail flows (ADR-0071, `D18.1`): the one token table, the proven-address
-- column, and the nullable staff hash.
--
-- Generated by drizzle-kit and extended by hand with the backfill in the last
-- statement, which no diff of the schema can produce: it is a statement about
-- rows that already exist, not about the shape they live in.
--
-- Nothing here is expected to block (the `db-schema-change` rule for a
-- migrator that runs everything in one transaction, ADR-0060 §5). The table is
-- new; `ALTER COLUMN … DROP NOT NULL` and `ADD COLUMN` of a nullable column
-- with no default are both catalogue-only on PostgreSQL 16; the `UPDATE` walks
-- `users`, which is the one statement whose cost grows with the deployment and
-- which touches each row once.
--
-- No `GRANT` for the new table: migration `0008` set `ALTER DEFAULT PRIVILEGES
-- IN SCHEMA public` for the application role precisely so that a later
-- migration's table is usable without a grant nobody remembers to write
-- (ADR-0061 §1).
CREATE TYPE "public"."token_purpose" AS ENUM('verify_email', 'reset_password', 'change_email', 'staff_onboarding');--> statement-breakpoint
CREATE TABLE "account_tokens" (
	"id" uuid PRIMARY KEY NOT NULL,
	"purpose" "token_purpose" NOT NULL,
	"principal_type" "principal_type" NOT NULL,
	"principal_id" uuid NOT NULL,
	"token_hash" text NOT NULL,
	"payload" jsonb,
	"expires_at" timestamp with time zone NOT NULL,
	"consumed_at" timestamp with time zone,
	"ip" "inet",
	"user_agent" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "account_tokens_token_hash_unique" UNIQUE("token_hash")
);
--> statement-breakpoint
-- ADR-0071 §8, the delta on ADR-0017: an `invited` operator has **no**
-- password rather than a placeholder somebody had to invent. Widening a
-- constraint, so every existing row stays valid and no deployment is asked to
-- do anything before this runs.
ALTER TABLE "staff" ALTER COLUMN "password_hash" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "email_verified_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "account_tokens_principal_purpose_idx" ON "account_tokens" USING btree ("principal_type","principal_id","purpose");--> statement-breakpoint
CREATE INDEX "account_tokens_expires_at_idx" ON "account_tokens" USING btree ("expires_at");--> statement-breakpoint
-- The backfill (ADR-0071 §3, amended 2026-09-10 at `D18.1`).
--
-- Every account that existed before this migration was created under
-- ADR-0018's rule — registration made it `active` on the spot — so refusing it
-- now would punish a decision that was right when it was made, and would sign
-- out every customer of a deployment that upgrades. `now()` rather than
-- `created_at`: the column records when the address was *proven*, and the
-- honest answer for these rows is "at the upgrade, by fiat", not a date
-- somebody could mistake for evidence.
--
-- **Except a `pending_verification` row**, which is the amendment: that status
-- is not something registration produced, it is something a person or a seeder
-- put there deliberately, and such a row has proven nothing. Stamping it would
-- make `email_verified_at` disagree with `status` on the one row the
-- verification flow exists to move — and the `--dev` fixtures carry exactly
-- such a row, so the contradiction would ship in every clone.
--
-- `WHERE email_verified_at IS NULL` is what makes the statement idempotent: a
-- replay onto a database that already ran it updates nothing, and an address
-- verified for real between two runs keeps its own timestamp.
UPDATE "users" SET "email_verified_at" = now() WHERE "email_verified_at" IS NULL AND "status" <> 'pending_verification';
